    public var name: String
    public var ip: String
    public var udpPort: UInt16
    public var tcpPort: UInt16
    public var device: DeviceMeta?
    /**
     * Stable per-device grouping id (display-grade).
     */
    public var deviceId: String?
    /**
     * Product label running on the peer.
     */
    public var product: String?
    /**
     * Opaque application payload (mDNS-TXT style) — the host's richer
     * profile rides here; the engine never parses it.
     */
    public var extra: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(nodeId: String, name: String, ip: String, udpPort: UInt16, tcpPort: UInt16, device: DeviceMeta?, 
        /**
         * Stable per-device grouping id (display-grade).
         */deviceId: String?, 
        /**
         * Product label running on the peer.
         */product: String?, 
        /**
         * Opaque application payload (mDNS-TXT style) — the host's richer
         * profile rides here; the engine never parses it.
         */extra: String?) {
        self.nodeId = nodeId
        self.name = name
        self.ip = ip
        self.udpPort = udpPort
        self.tcpPort = tcpPort
        self.device = device
        self.deviceId = deviceId
        self.product = product
        self.extra = extra
    }
}

#if compiler(>=6)
extension DiscoveredPeer: Sendable {}
#endif


extension DiscoveredPeer: Equatable, Hashable {
    public static func ==(lhs: DiscoveredPeer, rhs: DiscoveredPeer) -> Bool {
        if lhs.nodeId != rhs.nodeId {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.ip != rhs.ip {
            return false
        }
        if lhs.udpPort != rhs.udpPort {
            return false
        }
        if lhs.tcpPort != rhs.tcpPort {
            return false
        }
        if lhs.device != rhs.device {
            return false
        }
        if lhs.deviceId != rhs.deviceId {
            return false
        }
        if lhs.product != rhs.product {
            return false
        }
        if lhs.extra != rhs.extra {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(nodeId)
        hasher.combine(name)
        hasher.combine(ip)
        hasher.combine(udpPort)
        hasher.combine(tcpPort)
        hasher.combine(device)
        hasher.combine(deviceId)
        hasher.combine(product)
        hasher.combine(extra)
    }
}



